mapper.select:
SELECT COUNT(1) FROM platform_access_token t INNER JOIN platform_access_client c ON c.id = t.client_id
AND c.client_code LIKE CONCAT(#{clientCode}, '%')
AND t.status = #{status}

SELECT t.id AS id, c.client_code AS clientCode, t.token_prefix AS tokenPrefix, t.status AS status, t.created_at AS createdAt FROM platform_access_token t INNER JOIN platform_access_client c ON c.id = t.client_id
AND c.client_code LIKE CONCAT(#{clientCode}, '%')
AND t.status = #{status}
ORDER BY t.id DESC LIMIT #{offset}, #{limit}
